type UseDeckScreenModelArgs = {
  mode: "decks" | "cards";
  desktopViewport: boolean;
  decksHeader: DeckScreenHeaderModel | null;
  cardsHeader: DeckScreenHeaderModel;
  decksContent: React.ReactNode;
  cardsPane: DeckScreenCardsPaneModel | null;
  mobileDock: DeckScreenDockModel | null;
};

export function useDeckScreenModel({
  mode,
  desktopViewport,
  decksHeader,
  cardsHeader,
  decksContent,
  cardsPane,
  mobileDock,
}: UseDeckScreenModelArgs): DeckScreenModel {
  return React.useMemo(
    () => ({
      mode,
      desktopViewport,
      desktopHeader:
        mode === "decks"
          ? decksHeader
          : desktopViewport
            ? cardsHeader
            : null,
      decksContent: mode === "decks" ? decksContent : null,
      cardsPane: mode === "cards" ? cardsPane : null,
      mobileDock,
    }),
    [
      cardsHeader,
      cardsPane,
      decksContent,
      decksHeader,
      desktopViewport,
      mobileDock,
      mode,
    ],
  );
}

