import { describe, expect, it, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import { DeckDesktopMenu } from "./DeckDesktopMenu";

describe("DeckDesktopMenu", () => {
  it("reserves the title meta slot even when the deck header has no meta content", () => {
    const baseModel = {
      navigationLabel: "Nocards",
      onNavigation: vi.fn(),
      title: "Decks",
      trailingActions: [
        {
          id: "settings",
          label: "Open settings",
