  });

  it("renders the select action next to the back button", () => {
    render(
      <DeckDesktopMenu
        model={{
          navigationLabel: "Nocards",
          onNavigation: vi.fn(),
          leadingActions: [
            { id: "back", label: "Go Back", onClick: vi.fn() },
