    );

    const buttons = screen.getAllByRole("button").map((button) => button.textContent);
    expect(buttons).toEqual(["", "Go Back", "Select", ""]);
  });

  it("renders the leading action before the primary action", () => {
    render(
      <DeckDesktopMenu
        model={{
          navigationLabel: "Nocards",
          onNavigation: vi.fn(),
          leadingActions: [
            { id: "add-deck", label: "Add deck", onClick: vi.fn() },
          ],
          trailingActions: [
            { id: "add-card", label: "Add card", onClick: vi.fn(), variant: "default" },
            {
              id: "settings",
              label: "Open settings",
              onClick: vi.fn(),
              iconOnly: true,
            },
          ],
        }}
      />,
    );

    const buttons = screen.getAllByRole("button").map((button) => button.textContent);
    expect(buttons).toEqual(["", "Add deck", "Add card", ""]);
  });

  it("does not depend on matchMedia for layout decisions", () => {
    Object.defineProperty(window, "matchMedia", {
      writable: true,
      value: vi.fn(),
    });

    render(
      <DeckDesktopMenu
        model={{
          navigationLabel: "Nocards",
          onNavigation: vi.fn(),
          trailingActions: [
            {
              id: "settings",
              label: "Open settings",
              onClick: vi.fn(),
              iconOnly: true,
            },
          ],
        }}
      />,
    );

    expect(window.matchMedia).not.toHaveBeenCalled();
  });
});

