const submitCreateDeck = React.useCallback(async () => {
  if (createDeckDuplicateTarget) {
    setCreateDeckOpen(false);
    setCreateDeckDraft("");
    router.replace(buildCardsUrl([createDeckDuplicateTarget.id]));
    return;
  }

  if (creatingDeckRef.current) {
    toastWithTimeout(setToast, "Deck is still saving");
    return;
  }
  if (!canSubmitCreateDeck) return;

  const draftName = normalizedCreateDeckName;
  const now = new Date().toISOString();
  const optimisticDeck: Deck = {
    id: createClientId("optimistic-deck-"),
    name: draftName,
    parentId: null,
    createdAt: now,
    updatedAt: now,
  };
  creatingDeckRef.current = true;
  setCreatingDeck(true);
  setPendingDeckIds((previous) => addUniqueId(previous, optimisticDeck.id));
  setCreateDeckOpen(false);
  setCreateDeckDraft("");
  applyDeckToCaches(optimisticDeck);
  toastWithTimeout(setToast, "Saving deck...");
  try {
    const created = await api.createDeck(draftName);
    replaceDeckInCaches(optimisticDeck.id, created);
    await Promise.all([
      queryClient.refetchQueries({ queryKey: libraryBootstrapKey, exact: true }),
      queryClient.refetchQueries({ queryKey: deckCatalogKey, exact: true }),
    ]);
    router.replace(buildCardsUrl([created.id]));
    toastWithTimeout(setToast, "Deck saved");
  } catch (error) {
    removeDeckFromCaches(optimisticDeck.id);
    setCreateDeckDraft(draftName);
    setCreateDeckOpen(true);
    toastWithTimeout(setToast, "Deck could not save");
    console.warn("Failed to create deck", error);
  } finally {
    creatingDeckRef.current = false;
    setPendingDeckIds((previous) => removeId(previous, optimisticDeck.id));
    setCreatingDeck(false);
  }
}, [
  applyDeckToCaches,
  canSubmitCreateDeck,
  createDeckDuplicateTarget,
  deckCatalogKey,
  libraryBootstrapKey,
  normalizedCreateDeckName,
  queryClient,
  removeDeckFromCaches,
  replaceDeckInCaches,
  router,
]);

